"""Optimizers that run entirely on DirectML.

Adam: torch.optim.Adam updates its first moment with lerp_, which torch-directml
does not implement, so that step falls back to the CPU. This version computes the
same update with mul_ + add_, which run on the GPU. Otherwise it follows
torch.optim.Adam (L2 weight decay added to the gradient, optional AMSGrad).

ScheduleFreeAdamW: Schedule-Free AdamW (Defazio et al., "The Road Less Scheduled",
2024), following the simplified reference implementation of Meta's `schedulefree`
package (AdamWScheduleFreeReference), with the same defaults.
"""

import math

import torch


class Adam(torch.optim.Optimizer):
    def __init__(
        self,
        params,
        lr: float = 1e-3,
        betas: tuple[float, float] = (0.9, 0.999),
        eps: float = 1e-8,
        weight_decay: float = 0.0,
        amsgrad: bool = False,
    ):
        if lr < 0.0:
            raise ValueError(f"Invalid learning rate: {lr}")
        if eps < 0.0:
            raise ValueError(f"Invalid epsilon value: {eps}")
        if not 0.0 <= betas[0] < 1.0:
            raise ValueError(f"Invalid beta parameter at index 0: {betas[0]}")
        if not 0.0 <= betas[1] < 1.0:
            raise ValueError(f"Invalid beta parameter at index 1: {betas[1]}")
        if weight_decay < 0.0:
            raise ValueError(f"Invalid weight_decay value: {weight_decay}")
        defaults = dict(lr=lr, betas=betas, eps=eps, weight_decay=weight_decay, amsgrad=amsgrad)
        super().__init__(params, defaults)

    @torch.no_grad()
    def step(self, closure=None):
        loss = None
        if closure is not None:
            with torch.enable_grad():
                loss = closure()

        for group in self.param_groups:
            lr = group["lr"]
            beta1, beta2 = group["betas"]
            eps = group["eps"]
            weight_decay = group["weight_decay"]
            amsgrad = group["amsgrad"]

            for param in group["params"]:
                if param.grad is None:
                    continue
                grad = param.grad
                if grad.is_sparse:
                    raise RuntimeError("Adam does not support sparse gradients")

                state = self.state[param]
                if not state:
                    state["step"] = 0
                    state["exp_avg"] = torch.zeros_like(param, memory_format=torch.preserve_format)
                    state["exp_avg_sq"] = torch.zeros_like(param, memory_format=torch.preserve_format)
                    if amsgrad:
                        state["max_exp_avg_sq"] = torch.zeros_like(
                            param, memory_format=torch.preserve_format
                        )

                state["step"] += 1
                step = state["step"]
                exp_avg = state["exp_avg"]
                exp_avg_sq = state["exp_avg_sq"]

                if weight_decay != 0.0:
                    grad = grad.add(param, alpha=weight_decay)

                # First moment: replaces exp_avg.lerp_(grad, 1 - beta1).
                exp_avg.mul_(beta1).add_(grad, alpha=1.0 - beta1)
                # Second moment.
                exp_avg_sq.mul_(beta2).addcmul_(grad, grad, value=1.0 - beta2)

                bias_correction1 = 1.0 - beta1**step
                bias_correction2_sqrt = math.sqrt(1.0 - beta2**step)

                if amsgrad:
                    max_exp_avg_sq = state["max_exp_avg_sq"]
                    torch.maximum(max_exp_avg_sq, exp_avg_sq, out=max_exp_avg_sq)
                    denom = (max_exp_avg_sq.sqrt() / bias_correction2_sqrt).add_(eps)
                else:
                    denom = (exp_avg_sq.sqrt() / bias_correction2_sqrt).add_(eps)

                param.addcdiv_(exp_avg, denom, value=-lr / bias_correction1)

        return loss


class ScheduleFreeAdamW(torch.optim.Optimizer):
    """Schedule-Free AdamW: no learning-rate schedule, but an average of the iterates.

    Per weight it keeps three sequences: z (plain AdamW-like steps without momentum),
    x (a weighted running average of z, the method's output) and y (the point where
    gradients are computed, y = beta1 * x + (1 - beta1) * z). During training the
    model's weights hold y; call eval() to switch them to x (for evaluation and saving)
    and train() to switch back before the next step.

    The learning rate warms up linearly over warmup_steps. The averaging weight of each
    step is proportional to (largest learning rate so far) ** weight_lr_power.
    """

    def __init__(self, params, lr: float = 2.5e-3, betas: tuple[float, float] = (0.9, 0.999),
                 eps: float = 1e-8, weight_decay: float = 0.0, warmup_steps: int = 0,
                 weight_lr_power: float = 2.0):
        if lr < 0.0:
            raise ValueError(f"Invalid learning rate: {lr}")
        if not 0.0 <= betas[0] < 1.0 or not 0.0 <= betas[1] < 1.0:
            raise ValueError(f"Invalid betas: {betas}")
        defaults = dict(lr=lr, betas=betas, eps=eps, weight_decay=weight_decay,
                        warmup_steps=warmup_steps, weight_lr_power=weight_lr_power)
        super().__init__(params, defaults)
        self.step_count = 0
        self.lr_max = 0.0
        self.weight_sum = 0.0
        self.train_mode = True  # the model starts with y = x = z = the initial weights

    @torch.no_grad()
    def eval(self) -> None:
        """Put the averaged weights x into the model (for evaluation and saving)."""
        if self.train_mode:
            for p in self._params_with_state():
                p.copy_(self.state[p]["x"])
            self.train_mode = False

    @torch.no_grad()
    def train(self) -> None:
        """Put the gradient point y back into the model before training continues."""
        if not self.train_mode:
            for p in self._params_with_state():
                p.copy_(self.state[p]["y"])
            self.train_mode = True

    def _params_with_state(self):
        for group in self.param_groups:
            for p in group["params"]:
                if "x" in self.state[p]:
                    yield p

    @torch.no_grad()
    def step(self, closure=None):
        if not self.train_mode:
            raise RuntimeError("ScheduleFreeAdamW.step() called in eval mode; call train() first")
        loss = None
        if closure is not None:
            with torch.enable_grad():
                loss = closure()

        k = self.step_count
        for group in self.param_groups:
            beta1, beta2 = group["betas"]
            eps = group["eps"]
            warmup = group["warmup_steps"]
            lr = group["lr"] * ((k + 1) / warmup if k < warmup else 1.0)
            self.lr_max = max(self.lr_max, lr)
            weight = self.lr_max ** group["weight_lr_power"]
            self.weight_sum += weight
            average_weight = weight / self.weight_sum if self.weight_sum > 0 else 0.0
            bias_correction2 = 1.0 - beta2 ** (k + 1)

            for p in group["params"]:
                if p.grad is None:
                    continue
                grad = p.grad
                state = self.state[p]
                if not state:
                    state["z"] = p.detach().clone()
                    state["x"] = p.detach().clone()
                    state["y"] = p.detach().clone()
                    state["exp_avg_sq"] = torch.zeros_like(p)
                z, x, y, exp_avg_sq = state["z"], state["x"], state["y"], state["exp_avg_sq"]

                if group["weight_decay"] != 0.0:
                    z.sub_(y, alpha=lr * group["weight_decay"])  # decoupled decay at y

                exp_avg_sq.mul_(beta2).addcmul_(grad, grad, value=1.0 - beta2)
                denom = (exp_avg_sq / bias_correction2).sqrt_().add_(eps)
                z.addcdiv_(grad, denom, value=-lr)

                # x: weighted running average of z; y: the next gradient point.
                x.mul_(1.0 - average_weight).add_(z, alpha=average_weight)
                y.copy_(x * beta1 + z * (1.0 - beta1))
                p.copy_(y)

        self.step_count = k + 1
        return loss
